using HRIS.Api.Common; using HRIS.Api.Exceptions; using HRIS.Api.Models; using HRIS.Api.Models.Enums; using HRIS.Api.Data; using Microsoft.EntityFrameworkCore;
namespace HRIS.Api.Services; public class FamilyChangeApprovalHandler : IApprovalHandler { private readonly AppDbContext _db; public FamilyChangeApprovalHandler(AppDbContext db)=>_db=db; public string RequestType=>ApprovalRequestTypes.FamilyChange; public async Task OnCompletedAsync(ApprovalRequest request,ApprovalRequestStatus finalStatus){var x=await _db.FamilyChangeRequests.FindAsync(request.RequestRefId)??throw new NotFoundException("Permintaan perubahan keluarga tidak ditemukan."); x.Status=finalStatus switch{ApprovalRequestStatus.Approved=>"Approved",ApprovalRequestStatus.Rejected=>"Rejected",ApprovalRequestStatus.Cancelled=>"Cancelled",_=>x.Status}; if(finalStatus!=ApprovalRequestStatus.Approved){await _db.SaveChangesAsync();return;} if(x.Action.Equals("Add",StringComparison.OrdinalIgnoreCase)){_db.EmployeeFamilies.Add(new EmployeeFamily{EmployeeId=x.EmployeeId,FamilyName=x.FamilyName,RelationshipId=x.RelationshipId,GenderId=x.GenderId,BirthDate=x.BirthDate,IsDependent=x.IsDependent,WeddingDate=x.WeddingDate});} else {var family=await _db.EmployeeFamilies.FirstOrDefaultAsync(f=>f.Id==x.FamilyId&&f.EmployeeId==x.EmployeeId)??throw new NotFoundException("Data keluarga target tidak ditemukan."); if(x.Action.Equals("Delete",StringComparison.OrdinalIgnoreCase)) _db.EmployeeFamilies.Remove(family); else {family.FamilyName=x.FamilyName;family.RelationshipId=x.RelationshipId;family.GenderId=x.GenderId;family.BirthDate=x.BirthDate;family.IsDependent=x.IsDependent;family.WeddingDate=x.WeddingDate;}} await _db.SaveChangesAsync(); } }
